// Where applies predicates, ANDed together.
func (q Query) Where(ps ...Pred) Query {
	for i := range ps {
		q.leaf(ps[i])
		q.top++
	}
	return q
}

// WhenSet applies f(*v) only when v is non-nil — the optional-filter
// idiom without an if, and without the nil dereference WhereIf invites.
//
//	q = user.WhenSet(q, f.MinAge, user.Age.Gte)
//
// WhereIf takes an already-built Pred, so the caller has to evaluate
// user.Age.Gte(*f.MinAge) BEFORE the condition is tested — which panics
// on exactly the nil the condition was checking for. This takes the
// constructor instead, so nothing is dereferenced unless it is there.
//
// It still sets exactly one bit in the shape mask: a filter that is
// absent is a different SHAPE, compiled once, not a different value.
func WhenSet[T any](q Query, v *T, f func(T) Pred) Query {
	if v == nil {
		return q
	}
	return q.Where(f(*v))
}

// WhereIf applies a predicate only when cond holds.
func (q Query) WhereIf(cond bool, p Pred) Query {
	if !cond {
		return q
	}
	return q.Where(p)
}

// Any ORs its arguments and ANDs the group with the rest of the query:
// Where(a).Any(b, c) is a AND (b OR c).
func (q Query) Any(ps ...Pred) Query {
	if len(ps) == 0 {
		return q
	}
	for i := range ps {
		q.leaf(ps[i])
	}
	q.push(runtime.MakeGroup(runtime.KOr, uint32(len(ps))))
	q.top++
	return q
}

// Not negates one predicate and ANDs it with the rest.
func (q Query) Not(p Pred) Query {
	q.leaf(p)
	q.push(runtime.MakeGroup(runtime.KNot, 1))
	q.top++
	return q
}

// NotAny negates a disjunction: NOT (a OR b).
func (q Query) NotAny(ps ...Pred) Query {
	if len(ps) == 0 {
		return q
	}
	for i := range ps {
		q.leaf(ps[i])
	}
	q.push(runtime.MakeGroup(runtime.KOr, uint32(len(ps))))
	q.push(runtime.MakeGroup(runtime.KNot, 1))
	q.top++
	return q
}

// Grp is one conjunction, built by And, that AnyOf ORs with the others.
//
// It holds the predicates rather than tokens because the ARENA a value
// lands in is chosen by leaf, in stream order, and a group has no stream
// position until AnyOf gives it one.
type Grp struct{ ps []Pred }

// And groups predicates into one conjunction, so AnyOf can OR whole
// conjunctions rather than single predicates:
//
//	q.AnyOf(And(Status.Eq("paid"), Total.Gt(big)),
//	        And(Status.Eq("trial"), Total.Gt(small)))
//
// is (status = $1 AND total > $2) OR (status = $3 AND total > $4). Any
// ORs single predicates and cannot say this: an advanced-search screen
// whose rows are each a field, an operator and a value produces exactly
// this shape, and without it the query has to be written in SQL.
//
// The variadic slice does not escape — AnyOf reads it and returns — so a
// warm call still builds its SQL without allocating.
func And(ps ...Pred) Grp { return Grp{ps: ps} }

// AnyOf ORs its groups and ANDs the result with the rest of the query.
//
// An empty group contributes nothing, so a screen that builds one group
// per filled-in filter row needs no special case for the rows the user
// left blank. A group of one predicate is that predicate: the SQL carries
// no parentheses it did not need, which keeps the statement — and so the
// shape it is cached under — the same as the equivalent Any.
func (q Query) AnyOf(gs ...Grp) Query {
	n := uint32(0)
	for i := range gs {
		if len(gs[i].ps) == 0 {
			continue
		}
		for j := range gs[i].ps {
			q.leaf(gs[i].ps[j])
		}
		if len(gs[i].ps) > 1 {
			q.push(runtime.MakeGroup(runtime.KAnd, uint32(len(gs[i].ps))))
		}
		n++
	}
	if n == 0 {
		return q
	}
	if n > 1 {
		q.push(runtime.MakeGroup(runtime.KOr, n))
	}
	q.top++
	return q
}

// NotAnyOf negates the disjunction AnyOf builds: NOT ((a AND b) OR c).
func (q Query) NotAnyOf(gs ...Grp) Query {
	before := q.top
	q = q.AnyOf(gs...)
	if q.top == before {
		return q
	}
	q.push(runtime.MakeGroup(runtime.KNot, 1))
	return q
}

// leaf records one predicate: its value goes to the arena for its type,
// its structure to the token stream.
func (q *Query) leaf(p Pred) {
	if p.op == opIn || p.op == opNotIn || p.op == opArrayContains || p.op == opArrayContainedBy || p.op == opArrayOverlaps || p.op == opHasAnyKey || p.op == opHasAllKeys || p.op == opJSONTextLikeAny {
		switch p.col {
		case 0:
			if int(q.nar) >= 3 {
				q.over = true
				return
			}
			q.anyRaw[q.nar] = p.anyRaw
			q.nar++
		case 3:
			if int(q.nar) >= 3 {
				q.over = true
				return
			}
			q.anyRaw[q.nar] = p.anyRaw
			q.nar++
		case 4:
			if int(q.nar) >= 3 {
				q.over = true
				return
			}
			q.anyRaw[q.nar] = p.anyRaw
			q.nar++
		case 5:
			if int(q.nar) >= 3 {
				q.over = true
				return
			}
			q.anyRaw[q.nar] = p.anyRaw
			q.nar++
		case 6:
			if int(q.nas) >= 3 {
				q.over = true
				return
			}
			q.anyStr[q.nas] = p.anyStr
			q.nas++
		case 7:
			if int(q.nas) >= 3 {
				q.over = true
				return
			}
			q.anyStr[q.nas] = p.anyStr
			q.nas++
		case 8:
			if int(q.nas) >= 3 {
				q.over = true
				return
			}
			q.anyStr[q.nas] = p.anyStr
			q.nas++
		case 9:
			if int(q.nas) >= 3 {
				q.over = true
				return
			}
			q.anyStr[q.nas] = p.anyStr
			q.nas++
		case 10:
			if int(q.nas) >= 3 {
				q.over = true
				return
			}
			q.anyStr[q.nas] = p.anyStr
			q.nas++
		case 11:
			if int(q.nas) >= 3 {
				q.over = true
				return
			}
			q.anyStr[q.nas] = p.anyStr
			q.nas++
		case 12:
			if int(q.nas) >= 3 {
				q.over = true
				return
			}
			q.anyStr[q.nas] = p.anyStr
			q.nas++
		case 13:
			if int(q.nas) >= 3 {
				q.over = true
				return
			}
			q.anyStr[q.nas] = p.anyStr
			q.nas++
		case 14:
			if int(q.nas) >= 3 {
				q.over = true
				return
			}
			q.anyStr[q.nas] = p.anyStr
			q.nas++
		}
		q.push(runtime.MakeLeaf(uint32(p.op), uint32(p.col)))
		return
	}
	if p.op == opIsNull || p.op == opIsNotNull || p.op == opJSONIsEmpty || p.op == opNullOrEmpty {
		q.push(runtime.MakeLeaf(uint32(p.op), uint32(p.col)))
		return
	}
	switch p.col {
	case 0:
		if int(q.nr) >= 4 {
			q.over = true
			return
		}
		q.raws[q.nr] = p.raw
		q.nr++
	case 1:
		if int(q.ntm) >= 4 {
			q.over = true
			return
		}
		q.tims[q.ntm] = p.tim
		q.ntm++
	case 2:
		if int(q.ntm) >= 4 {
			q.over = true
			return
		}
		q.tims[q.ntm] = p.tim
		q.ntm++
	case 3:
		if int(q.nr) >= 4 {
			q.over = true
			return
		}
		q.raws[q.nr] = p.raw
		q.nr++
	case 4:
		if int(q.nr) >= 4 {
			q.over = true
			return
		}
		q.raws[q.nr] = p.raw
		q.nr++
	case 5:
		if int(q.nr) >= 4 {
			q.over = true
			return
		}
		q.raws[q.nr] = p.raw
		q.nr++
	case 6:
		if int(q.ns) >= 6 {
			q.over = true
			return
		}
		q.strs[q.ns] = p.str
		q.ns++
	case 7:
		if int(q.ns) >= 6 {
			q.over = true
			return
		}
		q.strs[q.ns] = p.str
		q.ns++
	case 8:
		if int(q.ns) >= 6 {
			q.over = true
			return
		}
		q.strs[q.ns] = p.str
		q.ns++
	case 9:
		if int(q.ns) >= 6 {
			q.over = true
			return
		}
		q.strs[q.ns] = p.str
		q.ns++
	case 10:
		if int(q.njs) >= 2 {
			q.over = true
			return
		}
		q.jsns[q.njs] = p.jsn
		q.njs++
	case 11:
		if int(q.njs) >= 2 {
			q.over = true
			return
		}
		q.jsns[q.njs] = p.jsn
		q.njs++
	case 12:
		if int(q.njs) >= 2 {
			q.over = true
			return
		}
		q.jsns[q.njs] = p.jsn
		q.njs++
	case 13:
		if int(q.njs) >= 2 {
			q.over = true
			return
		}
		q.jsns[q.njs] = p.jsn
		q.njs++
	case 14:
		if int(q.njs) >= 2 {
			q.over = true
			return
		}
		q.jsns[q.njs] = p.jsn
		q.njs++
	case 15:
		if int(q.ntm) >= 4 {
			q.over = true
			return
		}
		q.tims[q.ntm] = p.tim
		q.ntm++
	}
	q.push(runtime.MakeLeaf(uint32(p.op), uint32(p.col)))
}

// Relation existence — the semi-join. HasPosts() matches rows with at
// least one related row; HasNoPosts() matches the rest. Both compose
// under Where/Any/Not like any predicate, because both lower to constant
// fragments: no bound value, one compiled statement per structure.
func HasIncidents() Pred   { return Pred{col: 16, op: opExists} }
func HasNoIncidents() Pred { return Pred{col: 16, op: opNotExists} }

