func fragOf(op, col uint32) runtime.Frag {
	// Bounded by the table, not nCols: existence pseudo-columns live past
	// the real ones. Order, ident and arena lookups stay nCols-bounded,
	// so a pseudo-column can never be ordered by, cursored on, or bound.
	if int(col) >= len(fragTable) || int(op) >= len(fragTable[0]) {
		return runtime.Frag{}
	}
	return fragTable[col][op]
}

// defaultOrder is what a query with no Order() uses.
//
// It is never empty. A read without ORDER BY has no defined order, so
// paging one is a bug waiting for a plan change to expose it — and the
// primary key is the cheapest total order available.
var defaultOrder = [1]runtime.Tok{
	runtime.MakeOrder(runtime.Asc, 0), // id
}

var (
	cache       = runtime.NewTreeCache()
	offsetCache = runtime.NewTreeCache()
	countCache  = runtime.NewTreeCache()
	existsCache = runtime.NewTreeCache()
)

// Shapes reports how many distinct query structures have compiled.
// `storm lint` uses it to catch a builder minting a statement per request.
func Shapes() int { return cache.Shapes() }

// ShapeFlushes reports how many times a shape cache in this package hit
// runtime.ShapeCap and dropped. Zero is the expected value forever:
// nonzero means a call site is minting structures from request data
// rather than from code, and the fix is that call site, not a bigger
// cap. Export it as a gauge — it is the cheapest early warning that a
// filter screen turned into 2^n statements.
func ShapeFlushes() int {
	return cache.Flushes() + offsetCache.Flushes() +
		countCache.Flushes() + existsCache.Flushes() +
		updAllCache.Flushes() + delAllCache.Flushes()
}

// stmtFor compiles a read. LIMIT and LIMIT/OFFSET are different
// statements with different placeholder counts, so they get different
// caches rather than a sentinel token muddying the key.
func stmtFor(toks []runtime.Tok, withOffset bool, lock uint8) *runtime.Stmt {
	i, suffix := 0, limitSuffix
	if withOffset {
		i, suffix = 1, limitOffsetSuffix
	}
	c := lockCaches[lock][i]
	suffix += lockSuffix[lock]
	if st := c.Get(toks); st != nil {
		return st
	}
	return c.Put(toks, runtime.SpliceTreeWhere(selectPrefix, softDeleteWhere, toks, lowering, suffix))
}

// existsStmtFor compiles the existence probe: SELECT 1, no ORDER BY,
// LIMIT 1 — the planner stops at the first matching tuple instead of
// sorting every match to return the "first" of an order nobody reads.
func existsStmtFor(toks []runtime.Tok) *runtime.Stmt {
	if st := existsCache.Get(toks); st != nil {
		return st
	}
	return existsCache.Put(toks, runtime.SpliceTreeWhere(existsPrefix, softDeleteWhere, toks, lowering, existsSuffix))
}

func countStmtFor(toks []runtime.Tok) *runtime.Stmt {
	if st := countCache.Get(toks); st != nil {
		return st
	}
	// A count ignores ordering as well as LIMIT: ordering a scalar is
	// wasted work, and the token stream is trimmed before it gets here.
	return countCache.Put(toks, runtime.SpliceTreeWhere(countPrefix, softDeleteWhere, toks, lowering, ""))
}

// WithDeleted reads the marked rows as well as the live ones. All, One,
// Count, Exists, Take and the projections honour it; every other terminal refuses it,
// rather than quietly answering about the live rows only.
func (q Query) WithDeleted() Query { q.deleted = true; return q }

var (
	deletedReads = func() [7][2]*runtime.TreeCache {
		var cs [7][2]*runtime.TreeCache
		for i := range cs {
			cs[i][0], cs[i][1] = runtime.NewTreeCache(), runtime.NewTreeCache()
		}
		return cs
	}()
	deletedCount  = runtime.NewTreeCache()
	deletedExists = runtime.NewTreeCache()
)

func (q Query) readStmt(toks []runtime.Tok) *runtime.Stmt {
	if !q.deleted {
		return stmtFor(toks, q.offset > 0, q.lock)
	}
	i, suffix := 0, limitSuffix
	if q.offset > 0 {
		i, suffix = 1, limitOffsetSuffix
	}
	c := deletedReads[q.lock][i]
	if st := c.Get(toks); st != nil {
		return st
	}
	return c.Put(toks, runtime.SpliceTree(selectPrefix, toks, lowering, suffix+lockSuffix[q.lock]))
}

func (q Query) countStmt(toks []runtime.Tok) *runtime.Stmt {
	if !q.deleted {
		return countStmtFor(toks)
	}
	if st := deletedCount.Get(toks); st != nil {
		return st
	}
	return deletedCount.Put(toks, runtime.SpliceTree(countPrefix, toks, lowering, ""))
}

func (q Query) existsStmt(toks []runtime.Tok) *runtime.Stmt {
	if !q.deleted {
		return existsStmtFor(toks)
	}
	if st := deletedExists.Get(toks); st != nil {
		return st
	}
	return deletedExists.Put(toks, runtime.SpliceTree(existsPrefix, toks, lowering, existsSuffix))
}

const (
	distinctOpen = "SELECT DISTINCT ON ("
	distinctSep  = ", "
	distinctTail = ") \"id\", \"created_at\", \"updated_at\", \"project_id\", \"definition_id\", \"parent_instance_id\", \"parent_node_id\", \"status\", \"business_key\", \"variables\", \"tokens\", \"completed_nodes\", \"compensated_nodes\", \"multi_instance\", \"joins\", \"deleted_at\" FROM \"process_instances\""
)

// distinctCaches are AllDistinctOn's, without and with an offset. The
// key is the stream and then n, which the stream alone does not carry.
var distinctCaches = [2]*runtime.TreeCache{runtime.NewTreeCache(), runtime.NewTreeCache()}

var errDistinctOn = errors.New(
	"storm: AllDistinctOn keeps the first row of each run of the query's first n order terms; n must be between one and the number of terms Order set, and the query must not lock rows")

// distinctStmtFor compiles one (stream, n), once.
func distinctStmtFor(key, toks []runtime.Tok, n int, withOffset bool) *runtime.Stmt {
	i, suffix := 0, limitSuffix
	if withOffset {
		i, suffix = 1, limitOffsetSuffix
	}
	c := distinctCaches[i]
	if st := c.Get(key); st != nil {
		return st
	}
	prefix := distinctOpen
	for _, t := range toks {
		if t.Kind() != runtime.KOrder || n == 0 {
			continue
		}
		if prefix != distinctOpen {
			prefix += distinctSep
		}
		prefix += identTable[t.Col()]
		n--
	}
	return c.Put(key, runtime.SpliceTreeWhere(prefix+distinctTail, softDeleteWhere, toks, lowering, suffix))
}

// AllDistinctOn runs the query keeping one row for each distinct value
// of its first n order terms: the first, in the query's order. Order
// by the key and then by what picks the row:
//
//	q.Order(Project.Asc(), Key.Asc(), CreatedAt.Desc()).AllDistinctOn(ctx, ex, 2, nil)
//
// is each project's and key's newest row. Limit and Offset count the
// rows kept. n outside the explicit order, or a row lock, is refused.
func (q Query) AllDistinctOn(ctx context.Context, ex runtime.Executor, n int, dst []Row) ([]Row, error) {
	if err := q.Err(); err != nil {
		return dst, err
	}
	if n < 1 || n > int(q.no) || q.lock != 0 {
		return dst, errDistinctOn
	}
	var buf [21]runtime.Tok
	toks := q.stream(&buf)
	var kb [22]runtime.Tok
	key := kb[:copy(kb[:], toks)+1]
	key[len(key)-1] = runtime.Tok(n)
	st := distinctStmtFor(key, toks, n, q.offset > 0)
	if st.Err != nil {
		return dst, st.Err
	}
	var sl runtime.Slab
	sl.Reserve(st.SlabHint())
	b := binders.Get()
	defer putBinder(b)
	rows, err := ex.Query(ctx, st.SQL, q.bind(b))
	if err != nil {
		return dst, err
	}
	defer rows.Close()
	for rows.Next() {
		dst = append(dst, Row{})
		if err := scan(rows.RawValues(), &dst[len(dst)-1], &sl); err != nil {
			return dst, err
		}
	}
	st.ObserveSlab(sl.Size())
	return dst, rows.Err()
}

// Composition seams, for the generated CONTEXT package and it alone:
// cross-table statements (a filtered semi-join spans two packages) are
// assembled there from each side's tokens, fragments and bindings. Ids
// only — no SQL text and no value crosses here.

// FragOf is the compiled fragment table, exported for composition.
func FragOf(op, col uint32) runtime.Frag { return fragOf(op, col) }

// Lowering is this package's back-end text, exported for composition.
func Lowering() runtime.Lowering { return lowering }

// StmtPieces are the statement's constant parts, exported for composition.
func StmtPieces() (selectPfx, countPfx, limitSfx string) {
	return selectPrefix, countPrefix, limitSuffix
}

// PredToks appends this query's predicate stream to dst: top-level
// conjuncts reduced to one entry, order excluded.
func (q Query) PredToks(dst []runtime.Tok) []runtime.Tok {
	var buf [21]runtime.Tok
	return append(dst, q.preds(&buf)...)
}

// OrderToks appends this query's ordering — explicit, or the default
// unless Unordered.
func (q Query) OrderToks(dst []runtime.Tok) []runtime.Tok {
	if q.no == 0 {
		if q.noOrder {
			return dst
		}
		return append(dst, defaultOrder[:]...)
	}
	return append(dst, q.otoks[:q.no]...)
}

// Locked and Paged report a row lock and an Offset, which a statement
// composed around this query's read may have no place for.
func (q Query) Locked() bool { return q.lock != 0 }
func (q Query) Paged() bool  { return q.offset != 0 }

// Ordered reports an Order(), which a grouped read composed around this
// query's predicates has no place for.
func (q Query) Ordered() bool { return q.no > 0 }

// BindPreds binds this query's predicate values into b, appending to v.
func (q Query) BindPreds(b *Binder, v []any) []any {
	return append(v, q.bindPreds(b)...)
}

// BindPaging appends the LIMIT (and OFFSET when set) arguments.
func (q Query) BindPaging(b *Binder, v []any) []any {
	b.limit = q.limit
	v = append(v, &b.limit)
	if q.offset > 0 {
		b.offset = q.offset
		v = append(v, &b.offset)
	}
	return v
}

// Shape is a fingerprint of this query's structure — equal shapes share a
// compiled statement. Values do not contribute, which is the point.
func (q Query) Shape() uint64 {
	var buf [21]runtime.Tok
	return runtime.HashToks(q.stream(&buf))
}

// SQL returns the compiled text for this query's structure.
func (q Query) SQL() string {
	var buf [21]runtime.Tok
	return q.readStmt(q.stream(&buf)).SQL
}

// Scan decodes one row from raw wire bytes into r, copying text into sl.
//
// Exported for the context package, which assembles batched results and
// therefore has to decode rows it did not issue the query for.
func Scan(rv [][]byte, r *Row, sl *runtime.Slab) error { return scan(rv, r, sl) }

// scan decodes one row straight from the wire. No reflect, no `any`, no
// driver.Value: the generator knows every column's type already.
//
// It returns an error only for a value the Go type cannot carry — a
// numeric past 18 significant digits, or a NaN. Those must not become a
// plausible zero, and a row scanner is the last place that can tell.
func scan(rv [][]byte, r *Row, sl *runtime.Slab) error {
	copy(r.ID[:], rv[0])
	r.CreatedAt = runtime.Timestamptz(rv[1])
	r.UpdatedAt = runtime.Timestamptz(rv[2])
	copy(r.ProjectID[:], rv[3])
	copy(r.DefinitionID[:], rv[4])
	r.ParentInstanceID = runtime.Nullable(rv[5], runtime.UUID)
	r.ParentNodeID = runtime.NullText(rv[6], sl)
	r.Status = sl.Str(rv[7])
	r.BusinessKey = runtime.NullText(rv[8], sl)
	r.Variables = sl.Str(rv[9])
	r.Tokens = runtime.JSON(runtime.JSONB(rv[10], sl))
	r.CompletedNodes = runtime.JSON(runtime.JSONB(rv[11], sl))
	r.CompensatedNodes = runtime.JSON(runtime.JSONB(rv[12], sl))
	r.MultiInstance = runtime.JSON(runtime.JSONB(rv[13], sl))
	r.Joins = runtime.JSON(runtime.JSONB(rv[14], sl))
	r.DeletedAt = runtime.Nullable(rv[15], runtime.Timestamptz)
	return nil
}

type binder struct {
	vals   []any
	strs   [6]string
	raws   [4][16]byte
	tims   [4]time.Time
	jsns   [2]runtime.JSON
	anyRaw [3][][16]byte
	anyStr [3][]string
	limit  int64
	offset int64
}

var binders = runtime.NewPool(func() *binder {
	return &binder{vals: make([]any, 0, 17)}
})

// Binder is the pooled argument buffer.
type Binder = binder

func GetBinder() *Binder  { return binders.Get() }
func PutBinder(b *Binder) { putBinder(b) }

// putBinder clears every field that references memory OUTSIDE the binder
// before pooling it. A pooled binder otherwise PINS the caller's data —
// the slice behind an In(...) and the bytes behind every bound string —
// for as long as the pool holds it, which is forever. The numeric, time
// and uuid arenas are value arrays and pin nothing; vals points at the
// binder's own fields. A few nil stores against a round trip is free.
func putBinder(b *binder) {
	for i := range b.strs {
		b.strs[i] = ""
	}
	for i := range b.anyRaw {
		b.anyRaw[i] = nil
	}
	for i := range b.anyStr {
		b.anyStr[i] = nil
	}
	binders.Put(b)
}

// bindPreds copies arena values into the pooled buffer and points the
// []any at the buffer's own fields — boxing a pointer does not allocate.
// Count and Exists stop here: their statements carry no LIMIT or OFFSET.
func (q Query) bindPreds(b *binder) []any {
	v := b.vals[:0]
	var ns, nr, ntm, njs, nar, nas uint8
	for i := uint8(0); i < q.nt; i++ {
		t := q.toks[i]
		// KLeaf binds a predicate's value; KCol binds a keyset cursor's.
		// Both live in the same per-type arenas in stream order, so the
		// column switch below handles them identically. A KCol carries no
		// operator — its op is opNone, which matches no case in the
		// operator switch and falls straight through.
		if k := t.Kind(); k != runtime.KLeaf && k != runtime.KCol {
			continue
		}
		switch runtime.Op(t.Op()) {
		case opIsNull, opIsNotNull, opJSONIsEmpty, opNullOrEmpty:
			continue
		case opIn, opNotIn, opArrayContains, opArrayContainedBy, opArrayOverlaps, opHasAnyKey, opHasAllKeys, opJSONTextLikeAny:
			switch t.Col() {
			case 0:
				b.anyRaw[nar] = q.anyRaw[nar]
				v = append(v, &b.anyRaw[nar])
				nar++
			case 3:
				b.anyRaw[nar] = q.anyRaw[nar]
				v = append(v, &b.anyRaw[nar])
				nar++
			case 4:
				b.anyRaw[nar] = q.anyRaw[nar]
				v = append(v, &b.anyRaw[nar])
				nar++
			case 5:
				b.anyRaw[nar] = q.anyRaw[nar]
				v = append(v, &b.anyRaw[nar])
				nar++
			case 6:
				b.anyStr[nas] = q.anyStr[nas]
				v = append(v, &b.anyStr[nas])
				nas++
			case 7:
				b.anyStr[nas] = q.anyStr[nas]
				v = append(v, &b.anyStr[nas])
				nas++
			case 8:
				b.anyStr[nas] = q.anyStr[nas]
				v = append(v, &b.anyStr[nas])
				nas++
			case 9:
				b.anyStr[nas] = q.anyStr[nas]
				v = append(v, &b.anyStr[nas])
				nas++
			case 10:
				b.anyStr[nas] = q.anyStr[nas]
				v = append(v, &b.anyStr[nas])
				nas++
			case 11:
				b.anyStr[nas] = q.anyStr[nas]
				v = append(v, &b.anyStr[nas])
				nas++
			case 12:
				b.anyStr[nas] = q.anyStr[nas]
				v = append(v, &b.anyStr[nas])
				nas++
			case 13:
				b.anyStr[nas] = q.anyStr[nas]
				v = append(v, &b.anyStr[nas])
				nas++
			case 14:
				b.anyStr[nas] = q.anyStr[nas]
				v = append(v, &b.anyStr[nas])
				nas++
			}
			continue
		}
		switch t.Col() {
		case 0:
			b.raws[nr] = q.raws[nr]
			v = append(v, &b.raws[nr])
			nr++
		case 1:
			b.tims[ntm] = q.tims[ntm]
			v = append(v, &b.tims[ntm])
			ntm++
		case 2:
			b.tims[ntm] = q.tims[ntm]
			v = append(v, &b.tims[ntm])
			ntm++
		case 3:
			b.raws[nr] = q.raws[nr]
			v = append(v, &b.raws[nr])
			nr++
		case 4:
			b.raws[nr] = q.raws[nr]
			v = append(v, &b.raws[nr])
			nr++
		case 5:
			b.raws[nr] = q.raws[nr]
			v = append(v, &b.raws[nr])
			nr++
		case 6:
			b.strs[ns] = q.strs[ns]
			v = append(v, &b.strs[ns])
			ns++
		case 7:
			b.strs[ns] = q.strs[ns]
			v = append(v, &b.strs[ns])
			ns++
		case 8:
			b.strs[ns] = q.strs[ns]
			v = append(v, &b.strs[ns])
			ns++
		case 9:
			b.strs[ns] = q.strs[ns]
			v = append(v, &b.strs[ns])
			ns++
		case 10:
			b.jsns[njs] = q.jsns[njs]
			v = append(v, &b.jsns[njs])
			njs++
		case 11:
			b.jsns[njs] = q.jsns[njs]
			v = append(v, &b.jsns[njs])
			njs++
		case 12:
			b.jsns[njs] = q.jsns[njs]
			v = append(v, &b.jsns[njs])
			njs++
		case 13:
			b.jsns[njs] = q.jsns[njs]
			v = append(v, &b.jsns[njs])
			njs++
		case 14:
			b.jsns[njs] = q.jsns[njs]
			v = append(v, &b.jsns[njs])
			njs++
		case 15:
			b.tims[ntm] = q.tims[ntm]
			v = append(v, &b.tims[ntm])
			ntm++
		}
	}
	b.vals = v
	return v
}

// bind is bindPreds plus the paging arguments, in suffix order.
func (q Query) bind(b *binder) []any {
	v := q.bindPreds(b)
	b.limit = q.limit
	v = append(v, &b.limit)
	// An offset of zero is absent from the statement, so binding it
	// would leave an argument nothing consumes.
	if q.offset > 0 {
		b.offset = q.offset
		v = append(v, &b.offset)
	}
	b.vals = v
	return v
}

// All runs the query and decodes every row.
func (q Query) All(ctx context.Context, ex runtime.Executor, dst []Row) ([]Row, error) {
	var sl runtime.Slab
	return q.AllInto(ctx, ex, dst, &sl)
}

// AllInto lets the caller own the string arena.
func (q Query) AllInto(ctx context.Context, ex runtime.Executor, dst []Row, sl *runtime.Slab) ([]Row, error) {
	if err := q.readErr(); err != nil {
		return dst, err
	}
	var buf [21]runtime.Tok
	st := q.readStmt(q.stream(&buf))
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return dst, st.Err
	}
	sl.Reserve(st.SlabHint())
	b := binders.Get()
	defer putBinder(b)

	rows, err := ex.Query(ctx, st.SQL, q.bind(b))
	if err != nil {
		return dst, err
	}
	defer rows.Close()
	for rows.Next() {
		dst = append(dst, Row{})
		if err := scan(rows.RawValues(), &dst[len(dst)-1], sl); err != nil {
			return dst, err
		}
	}
	st.ObserveSlab(sl.Size())
	return dst, rows.Err()
}

// One returns the first row, if any.
func (q Query) One(ctx context.Context, ex runtime.Executor) (Row, bool, error) {
	var sl runtime.Slab
	var buf [1]Row
	out, err := q.Limit(1).AllInto(ctx, ex, buf[:0], &sl)
	if err != nil || len(out) == 0 {
		return Row{}, false, err
	}
	return out[0], true, nil
}

// Count ignores Limit: counting a truncated set is a bug, not a feature.
func (q Query) Count(ctx context.Context, ex runtime.Executor) (int64, error) {
	if err := q.readErr(); err != nil {
		return 0, err
	}
	if q.lock != 0 {
		return 0, errCountLocked
	}
	var buf [21]runtime.Tok
	st := q.countStmt(q.preds(&buf))
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	// bindPreds, not bind: a count has no LIMIT and no OFFSET. The old
	// form bound everything and sliced the last argument off, which was
	// the limit — unless Offset was set, in which case it silently kept
	// the limit and dropped the offset, and the statement mismatched.
	rows, err := ex.Query(ctx, st.SQL, q.bindPreds(b))
	if err != nil {
		return 0, err
	}
	defer rows.Close()
	var n int64
	if rows.Next() {
		n = runtime.Int8(rows.RawValues()[0])
	}
	return n, rows.Err()
}

// Exists asks the one-bit question with a one-bit statement: SELECT 1,
// no ORDER BY, LIMIT 1. It was previously One() with the row thrown
// away, which projected every column AND carried the default ordering —
// measured on 50k rows, the planner top-N-sorted all 16,667 matches to
// return the "first" of an order nobody was going to read.
func (q Query) Exists(ctx context.Context, ex runtime.Executor) (bool, error) {
	if err := q.readErr(); err != nil {
		return false, err
	}
	if q.lock != 0 {
		return false, errExistsLocked
	}
	var buf [21]runtime.Tok
	st := q.existsStmt(q.preds(&buf))
	if st.Err != nil {
		return false, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	rows, err := ex.Query(ctx, st.SQL, q.bindPreds(b))
	if err != nil {
		return false, err
	}
	defer rows.Close()
	return rows.Next(), rows.Err()
}

// Prepare resolves the structure and binds arguments without executing.
func (q Query) Prepare(b *Binder) (string, []any) {
	var buf [21]runtime.Tok
	return q.readStmt(q.stream(&buf)).SQL, q.bind(b)
}

// RefRow is the "Ref" projection: the same read, 1 column(s) instead of
// the whole row. Narrower tuples, no TOAST fetch for what nobody asked,
// and an index-only scan becomes POSSIBLE — the full-row read forecloses
// it by construction.
type RefRow struct {
	ID [16]byte
}

const refPrefix = `SELECT "id" FROM "process_instances"`

var (
	refCache       = runtime.NewTreeCache()
	refOffsetCache = runtime.NewTreeCache()
)

func refStmtFor(toks []runtime.Tok, withOffset bool) *runtime.Stmt {
	c, suffix := refCache, limitSuffix
	if withOffset {
		c, suffix = refOffsetCache, limitOffsetSuffix
	}
	if st := c.Get(toks); st != nil {
		return st
	}
	return c.Put(toks, runtime.SpliceTreeWhere(refPrefix, softDeleteWhere, toks, lowering, suffix))
}

var refDeletedCaches = [2]*runtime.TreeCache{runtime.NewTreeCache(), runtime.NewTreeCache()}

// refDeletedStmtFor is refStmtFor under WithDeleted: no soft-delete
// predicate, because the model let this table's call sites ask for that.
func refDeletedStmtFor(toks []runtime.Tok, withOffset bool) *runtime.Stmt {
	i, suffix := 0, limitSuffix
	if withOffset {
		i, suffix = 1, limitOffsetSuffix
	}
	c := refDeletedCaches[i]
	if st := c.Get(toks); st != nil {
		return st
	}
	return c.Put(toks, runtime.SpliceTree(refPrefix, toks, lowering, suffix))
}

func scanRef(rv [][]byte, r *RefRow, sl *runtime.Slab) error {
	copy(r.ID[:], rv[0])
	return nil
}

// AllRef runs the query projected to RefRow. Predicates, ordering, limit,
// offset and keyset all apply exactly as on All — a projection changes
// what a row CARRIES, never which rows qualify. (After takes the full Row;
// populate its ordering columns and the cursor works unchanged.)
func (q Query) AllRef(ctx context.Context, ex runtime.Executor) ([]RefRow, error) {
	var sl runtime.Slab
	return q.AllRefInto(ctx, ex, nil, &sl)
}

// AllRefInto lets the caller own the output slice and the arena, exactly
// as AllInto does — a projection's terminals mirror the full read's, so a
// hot loop reuses both and a benchmark compares like with like.
func (q Query) AllRefInto(ctx context.Context, ex runtime.Executor, dst []RefRow, sl *runtime.Slab) ([]RefRow, error) {
	if err := q.readErr(); err != nil {
		return dst, err
	}
	var buf [21]runtime.Tok
	pick := refStmtFor
	if q.deleted {
		pick = refDeletedStmtFor
	}
	st := pick(q.stream(&buf), q.offset > 0)
	if st.Err != nil {
		return dst, st.Err
	}
	sl.Reserve(st.SlabHint())
	b := binders.Get()
	defer putBinder(b)
	rows, err := ex.Query(ctx, st.SQL, q.bind(b))
	if err != nil {
		return dst, err
	}
	defer rows.Close()
	for rows.Next() {
		dst = append(dst, RefRow{})
		if err := scanRef(rows.RawValues(), &dst[len(dst)-1], sl); err != nil {
			return dst, err
		}
	}
	st.ObserveSlab(sl.Size())
	return dst, rows.Err()
}

// OneRef is AllRef stopped at one row.
func (q Query) OneRef(ctx context.Context, ex runtime.Executor) (RefRow, bool, error) {
	out, err := q.Limit(1).AllRef(ctx, ex)
	if err != nil || len(out) == 0 {
		return RefRow{}, false, err
	}
	return out[0], true, nil
}

