// The conflict encoding. One byte holds both which unique index an
// upsert names and what it does on collision, so the insert statement
// cache stays keyed by one mask and one byte:
//
//	0        no ON CONFLICT clause
//	1        ON CONFLICT DO NOTHING, on any unique index
//	2+2*i    target i, DO UPDATE
//	3+2*i    target i, DO NOTHING
const conflictAny = 1

// upsertTail builds the ON CONFLICT clause for one encoded conflict
// and one insert mask.
//
// The mask is what makes an upsert correct: it overwrites only the
// columns the caller ASSIGNED. Assigning every column would revert
// each one the caller left out to its default, on the row that
// already exists — a silent data loss that reads as an upsert working.
func upsertTail(conflict uint8, mask uint64) string {
	if conflict == conflictAny {
		return " ON CONFLICT DO NOTHING"
	}
	spec, i := conflictSpecs[(conflict-2)/2], (conflict-2)/2
	if conflict%2 == 1 {
		return spec + " DO NOTHING"
	}
	set := assignable(i, mask)
	if len(set) == 0 {
		// Nothing to overwrite. DO UPDATE SET with an empty list is not
		// SQL, and leaving the row alone is what the caller asked for.
		return spec + " DO NOTHING"
	}
	return spec + " DO UPDATE SET " + joinAssign(set)
}

// conflictSpecs is one inference specification per target, in
// declaration order. A PARTIAL unique index carries its predicate:
// PostgreSQL infers the index from the keys and the predicate
// together, and without it the insert fails at run time — on the first
// row that collides, which a test inserting distinct rows never sees.
var conflictSpecs = []string{
	" ON CONFLICT (\"id\")",
}

// assignable is the columns target i may overwrite, given the mask.
func assignable(i uint8, mask uint64) []string {
	set := make([]string, 0, 14)
	switch i {
	case 0:
		if mask&(1<<2) != 0 {
			set = append(set, "updated_at")
		}
		if mask&(1<<3) != 0 {
			set = append(set, "project_id")
		}
		if mask&(1<<4) != 0 {
			set = append(set, "definition_id")
		}
		if mask&(1<<5) != 0 {
			set = append(set, "parent_instance_id")
		}
		if mask&(1<<6) != 0 {
			set = append(set, "parent_node_id")
		}
		if mask&(1<<7) != 0 {
			set = append(set, "status")
		}
		if mask&(1<<8) != 0 {
			set = append(set, "business_key")
		}
		if mask&(1<<9) != 0 {
			set = append(set, "variables")
		}
		if mask&(1<<10) != 0 {
			set = append(set, "tokens")
		}
		if mask&(1<<11) != 0 {
			set = append(set, "completed_nodes")
		}
		if mask&(1<<12) != 0 {
			set = append(set, "compensated_nodes")
		}
		if mask&(1<<13) != 0 {
			set = append(set, "multi_instance")
		}
		if mask&(1<<14) != 0 {
			set = append(set, "joins")
		}
		if mask&(1<<15) != 0 {
			set = append(set, "deleted_at")
		}
	}
	return set
}

// OnConflictID upserts on the unique index over (id).
//
// The row that already exists keeps every column this insert did
// not assign. Follow with DoNothing() to leave it untouched
// entirely.
func (n *Ins) OnConflictID() *Ins {
	n.conflict = 2
	return n
}

// DoNothing makes the insert a no-op when the row is already there —
// the idempotent insert, and the commonest upsert there is.
//
// On its own it names no index, so ANY unique violation is the no-op:
//
//	n.DoNothing()                  // ON CONFLICT DO NOTHING
//	n.OnConflictID().DoNothing()  // only on that one index
//
// Insert then returns runtime.ErrNoRows when nothing was written,
// because DO NOTHING suppresses the RETURNING row: there is no row to
// return, and reporting a zero-valued one as inserted would be a lie.
func (n *Ins) DoNothing() *Ins {
	if n.conflict < 2 {
		n.conflict = conflictAny
		return n
	}
	n.conflict |= 1
	return n
}

// joinAssign renders the DO UPDATE SET list for the columns the caller
// assigned. The punctuation comes from the back end, never from here.
func joinAssign(set []string) string {
	out := ""
	for i, c := range set {
		if i > 0 {
			out += ", "
		}
		out += assignExcluded(c)
	}
	return out
}

var assignFor = map[string]string{
	"updated_at":         "\"updated_at\" = EXCLUDED.\"updated_at\"",
	"project_id":         "\"project_id\" = EXCLUDED.\"project_id\"",
	"definition_id":      "\"definition_id\" = EXCLUDED.\"definition_id\"",
	"parent_instance_id": "\"parent_instance_id\" = EXCLUDED.\"parent_instance_id\"",
	"parent_node_id":     "\"parent_node_id\" = EXCLUDED.\"parent_node_id\"",
	"status":             "\"status\" = EXCLUDED.\"status\"",
	"business_key":       "\"business_key\" = EXCLUDED.\"business_key\"",
	"variables":          "\"variables\" = EXCLUDED.\"variables\"",
	"tokens":             "\"tokens\" = EXCLUDED.\"tokens\"",
	"completed_nodes":    "\"completed_nodes\" = EXCLUDED.\"completed_nodes\"",
	"compensated_nodes":  "\"compensated_nodes\" = EXCLUDED.\"compensated_nodes\"",
	"multi_instance":     "\"multi_instance\" = EXCLUDED.\"multi_instance\"",
	"joins":              "\"joins\" = EXCLUDED.\"joins\"",
	"deleted_at":         "\"deleted_at\" = EXCLUDED.\"deleted_at\"",
}

func assignExcluded(c string) string { return assignFor[c] }

func stmtForInsert(mask uint64, conflict uint8) *runtime.Stmt {
	// The conflict clause is part of the statement, so it must be part of
	// the key. Packing it above the column bits keeps one cache for both.
	key := mask | uint64(conflict)<<nInsertable
	if st := insCache.Get(runtime.MaskKey{Dirty: key}); st != nil {
		return st
	}
	cols := make([]string, 0, nInsertable)
	for i := 0; i < nInsertable; i++ {
		if mask&(1<<uint(i)) != 0 {
			cols = append(cols, insCols[i])
		}
	}
	suffix := insReturning
	if conflict > 0 {
		suffix = upsertTail(conflict, mask) + insReturning
	}
	return insCache.Put(runtime.MaskKey{Dirty: key}, runtime.SpliceInsertWith(insPrefix, insParts, cols, insPlaceholder, suffix))
}

// Insert writes the assigned columns and reads every column back, so
// database-computed values land in the returned Row rather than needing a
// second SELECT that would race every other writer.
func (n *Ins) Insert(ctx context.Context, ex runtime.Executor) (Row, error) {
	if n.set == 0 {
		return Row{}, runtime.ErrNothingAssigned
	}
	st := stmtForInsert(n.set, n.conflict)
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return Row{}, st.Err
	}
	args := make([]any, 0, st.NArg)
	for i := 0; i < nInsertable; i++ {
		if n.set&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, n.row.ID)
		case 1:
			args = append(args, n.row.CreatedAt)
		case 2:
			args = append(args, n.row.UpdatedAt)
		case 3:
			args = append(args, n.row.ProjectID)
		case 4:
			args = append(args, n.row.DefinitionID)
		case 5:
			args = append(args, n.row.ParentInstanceID.Arg())
		case 6:
			args = append(args, n.row.ParentNodeID.Arg())
		case 7:
			args = append(args, n.row.Status)
		case 8:
			args = append(args, n.row.BusinessKey.Arg())
		case 9:
			args = append(args, n.row.Variables)
		case 10:
			args = append(args, n.row.Tokens)
		case 11:
			args = append(args, n.row.CompletedNodes)
		case 12:
			args = append(args, n.row.CompensatedNodes)
		case 13:
			args = append(args, n.row.MultiInstance)
		case 14:
			args = append(args, n.row.Joins)
		case 15:
			args = append(args, n.row.DeletedAt.Arg())
		}
	}
	var out Row
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return out, err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return out, err
		}
		if n.conflict != 0 && n.conflict%2 == 1 {
			// DO NOTHING suppresses RETURNING, so no row means the row was
			// already there — the success case of an idempotent insert.
			return out, runtime.ErrConflict
		}
		return out, runtime.ErrNoRow
	}
	var sl runtime.Slab
	if err := scan(rows.RawValues(), &out, &sl); err != nil {
		return out, err
	}
	return out, rows.Err()
}

// Inserts reports how many distinct INSERT column sets have compiled.
func Inserts() int { return insCache.Masks() }

// Insert writes one row and reads back every column, so database-computed
// defaults — a generated id, a now() timestamp — land in r rather than
// needing a second SELECT that would race every other writer.
//
// Every insertable column is written, including zero values. storm does
// not treat a zero as 'unset': that guess is why other ORMs cannot insert
// a false, a 0 or an empty string into a column with a default.
func Insert(ctx context.Context, ex runtime.Executor, r *Row) error {
	args := make([]any, 0, 16)
	args = append(args, r.ID)
	args = append(args, r.CreatedAt)
	args = append(args, r.UpdatedAt)
	args = append(args, r.ProjectID)
	args = append(args, r.DefinitionID)
	args = append(args, r.ParentInstanceID.Arg())
	args = append(args, r.ParentNodeID.Arg())
	args = append(args, r.Status)
	args = append(args, r.BusinessKey.Arg())
	args = append(args, r.Variables)
	args = append(args, r.Tokens)
	args = append(args, r.CompletedNodes)
	args = append(args, r.CompensatedNodes)
	args = append(args, r.MultiInstance)
	args = append(args, r.Joins)
	args = append(args, r.DeletedAt.Arg())
	rows, err := ex.Query(ctx, insertSQL, args)
	if err != nil {
		return err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return err
		}
		return runtime.ErrNoRow
	}
	// The returned strings live as long as this Slab, and the Slab lives
	// as long as r — a Row from an insert owns its own arena, unlike a Row
	// from a scan, which shares the result set's.
	var sl runtime.Slab
	if err := scan(rows.RawValues(), r, &sl); err != nil {
		return err
	}
	return rows.Err()
}

// copyCols is the fixed column list of a bulk load. Unlike Ins there is
// no mask: COPY sends one shape for the whole stream, so every row must
// supply every column and database defaults do not apply. Fill the row
// yourself, or use Create() per row and give up the bulk path.
var copyCols = []string{
	"id",
	"created_at",
	"updated_at",
	"project_id",
	"definition_id",
	"parent_instance_id",
	"parent_node_id",
	"status",
	"business_key",
	"variables",
	"tokens",
	"completed_nodes",
	"compensated_nodes",
	"multi_instance",
	"joins",
	"deleted_at",
}

// rowSource walks a []Row for CopyFrom without copying any of it.
type rowSource struct {
	rows []Row
	i    int
	buf  [16]any
}

func (s *rowSource) Next() bool {
	s.i++
	return s.i <= len(s.rows)
}

// Values reuses one buffer across every row, and fills it with POINTERS
// into the caller's slice rather than copies.
//
// Both halves matter. The driver consumes each slice before asking for
// the next, so one buffer is safe. And boxing a pointer into an `any`
// does not allocate while boxing a value does — at a thousand rows that
// is one allocation per column per row, or none. Measured: the first cut
// boxed values and cost 7 allocations per row.
func (s *rowSource) Values() []any {
	r := &s.rows[s.i-1]
	s.buf[0] = &r.ID
	s.buf[1] = &r.CreatedAt
	s.buf[2] = &r.UpdatedAt
	s.buf[3] = &r.ProjectID
	s.buf[4] = &r.DefinitionID
	s.buf[5] = r.ParentInstanceID.Ptr()
	s.buf[6] = r.ParentNodeID.Ptr()
	s.buf[7] = &r.Status
	s.buf[8] = r.BusinessKey.Ptr()
	s.buf[9] = &r.Variables
	s.buf[10] = &r.Tokens
	s.buf[11] = &r.CompletedNodes
	s.buf[12] = &r.CompensatedNodes
	s.buf[13] = &r.MultiInstance
	s.buf[14] = &r.Joins
	s.buf[15] = r.DeletedAt.Ptr()
	return s.buf[:]
}

func (s *rowSource) Err() error { return nil }

// InsertAll bulk-loads rows through the driver's COPY protocol: ONE round
// trip regardless of row count, because COPY is a different wire path and
// not a faster loop over INSERT.
//
// It returns no rows. COPY has no RETURNING, so a caller who needs
// database-generated ids must supply them — which is why the primary key
// is in copyCols and must be set on every row.
func InsertAll(ctx context.Context, ex runtime.Executor, rows []Row) (int64, error) {
	if len(rows) == 0 {
		return 0, nil
	}
	src := &rowSource{rows: rows}
	return ex.CopyFrom(ctx, "process_instances", copyCols, src)
}

// InsertOp is an insert as a queueable statement. It writes every
// insertable column, because a batch of a thousand rows that each chose
// a different column set would compile a thousand statements and defeat
// the point of batching them.
//
// WantRows is false: a batched insert reports a count. Asking for
// RETURNING here would mean scanning a result per statement, which is
// exactly the per-row work a batch exists to avoid.
func InsertOp(r Row) runtime.BatchOp {
	var mask uint64
	mask |= 1 << 0
	mask |= 1 << 1
	mask |= 1 << 2
	mask |= 1 << 3
	mask |= 1 << 4
	mask |= 1 << 5
	mask |= 1 << 6
	mask |= 1 << 7
	mask |= 1 << 8
	mask |= 1 << 9
	mask |= 1 << 10
	mask |= 1 << 11
	mask |= 1 << 12
	mask |= 1 << 13
	mask |= 1 << 14
	mask |= 1 << 15
	st := stmtForInsertNoReturn(mask, 0)
	args := make([]any, 0, 16)
	args = append(args, r.ID)
	args = append(args, r.CreatedAt)
	args = append(args, r.UpdatedAt)
	args = append(args, r.ProjectID)
	args = append(args, r.DefinitionID)
	args = append(args, r.ParentInstanceID.Arg())
	args = append(args, r.ParentNodeID.Arg())
	args = append(args, r.Status)
	args = append(args, r.BusinessKey.Arg())
	args = append(args, r.Variables)
	args = append(args, r.Tokens)
	args = append(args, r.CompletedNodes)
	args = append(args, r.CompensatedNodes)
	args = append(args, r.MultiInstance)
	args = append(args, r.Joins)
	args = append(args, r.DeletedAt.Arg())
	return runtime.BatchOp{SQL: st.SQL, Args: args}
}

// Op is this Ins as a queueable statement, conflict clause and all —
// the bulk upsert.
//
// InsertOp above takes a Row and writes every column, so a thousand of
// them share one statement. This takes the BUILDER, so it carries the
// mask and the ON CONFLICT the caller chose: ingesting a batch that
// should overwrite what is already there, or skip it, needs both and
// could otherwise only be done one round trip at a time.
//
// One statement per distinct (mask, conflict) pair, cached like every
// other. Assign the same columns on every row of a batch and it stays
// one; vary them and it is one per shape, which is the cost of asking.
//
// WantRows is false, as for InsertOp: a batch reports counts. A DO
// NOTHING that skipped a row is a zero in that count — the batch
// cannot say which rows were skipped, only how many.
func (n *Ins) Op() (runtime.BatchOp, error) {
	if n.set == 0 {
		return runtime.BatchOp{}, runtime.ErrNothingAssigned
	}
	st := stmtForInsertNoReturn(n.set, n.conflict)
	if st.Err != nil {
		return runtime.BatchOp{}, st.Err
	}
	args := make([]any, 0, st.NArg)
	for i := 0; i < nInsertable; i++ {
		if n.set&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, n.row.ID)
		case 1:
			args = append(args, n.row.CreatedAt)
		case 2:
			args = append(args, n.row.UpdatedAt)
		case 3:
			args = append(args, n.row.ProjectID)
		case 4:
			args = append(args, n.row.DefinitionID)
		case 5:
			args = append(args, n.row.ParentInstanceID.Arg())
		case 6:
			args = append(args, n.row.ParentNodeID.Arg())
		case 7:
			args = append(args, n.row.Status)
		case 8:
			args = append(args, n.row.BusinessKey.Arg())
		case 9:
			args = append(args, n.row.Variables)
		case 10:
			args = append(args, n.row.Tokens)
		case 11:
			args = append(args, n.row.CompletedNodes)
		case 12:
			args = append(args, n.row.CompensatedNodes)
		case 13:
			args = append(args, n.row.MultiInstance)
		case 14:
			args = append(args, n.row.Joins)
		case 15:
			args = append(args, n.row.DeletedAt.Arg())
		}
	}
	return runtime.BatchOp{SQL: st.SQL, Args: args}, nil
}

// stmtForInsertNoReturn is stmtForInsert without RETURNING, for the
// batch path. Its own cache: the two differ by a suffix, and sharing
// one would hand a batch the statement that asks for rows back.
func stmtForInsertNoReturn(mask uint64, conflict uint8) *runtime.Stmt {
	key := mask | uint64(conflict)<<nInsertable
	if st := insOpCache.Get(runtime.MaskKey{Dirty: key}); st != nil {
		return st
	}
	cols := make([]string, 0, nInsertable)
	for i := 0; i < nInsertable; i++ {
		if mask&(1<<uint(i)) != 0 {
			cols = append(cols, insCols[i])
		}
	}
	suffix := ""
	if conflict > 0 {
		suffix = upsertTail(conflict, mask)
	}
	return insOpCache.Put(runtime.MaskKey{Dirty: key}, runtime.SpliceInsertWith(insPrefix, insParts, cols, insPlaceholder, suffix))
}

// UpdateOp is this Mut's update as a queueable statement.
//
// The optimistic lock still applies, but the caller must check the
// affected count the batch reports: a stale write inside a batch is not
// an error the driver raises, it is a zero the caller has to notice.
//
// A server-side assignment is queued like any other, but the staged row
// is NOT refreshed: a batch reports counts, not rows. Use Update when
// the computed value is the thing you need.
func (m *Mut) UpdateOp() (runtime.BatchOp, bool) {
	if m.dirty == 0 && m.expr == 0 {
		return runtime.BatchOp{}, false
	}
	st := stmtForKey(m.key(), false)
	args := make([]any, 0, st.NArg)
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.UpdatedAt)
		case 1:
			args = append(args, m.row.ProjectID)
		case 2:
			args = append(args, m.row.DefinitionID)
		case 3:
			args = append(args, m.row.ParentInstanceID.Arg())
		case 4:
			args = append(args, m.row.ParentNodeID.Arg())
		case 5:
			args = append(args, m.row.Status)
		case 6:
			args = append(args, m.row.BusinessKey.Arg())
		case 7:
			args = append(args, m.row.Variables)
		case 8:
			args = append(args, m.row.Tokens)
		case 9:
			args = append(args, m.row.CompletedNodes)
		case 10:
			args = append(args, m.row.CompensatedNodes)
		case 11:
			args = append(args, m.row.MultiInstance)
		case 12:
			args = append(args, m.row.Joins)
		case 13:
			args = append(args, m.row.DeletedAt.Arg())
		}
	}
	args = append(args, m.row.ID)
	return runtime.BatchOp{SQL: st.SQL, Args: args}, true
}

// DeleteOp marks the row deleted, exactly as Delete does: a queued
// delete and a direct one must not differ in whether the row survives.
// HardDeleteOp is the queueable form of HardDelete.
func DeleteOp(iD [16]byte) runtime.BatchOp {
	return runtime.BatchOp{SQL: softDeleteSQL, Args: []any{iD}}
}

// HardDeleteOp removes the row for real, as a queueable statement.
func HardDeleteOp(iD [16]byte) runtime.BatchOp {
	return runtime.BatchOp{SQL: hardDeleteSQL, Args: []any{iD}}
}

// RestoreOp clears the mark, as a queueable statement.
func RestoreOp(iD [16]byte) runtime.BatchOp {
	return runtime.BatchOp{SQL: restoreSQL, Args: []any{iD}}
}

// Table is the table these statements write, so a Unit can order a mixed
// batch by foreign key without knowing what any of them are.
const Table = "process_instances"

// stmtForKey compiles the UPDATE for one (dirty, expr) pair, once.
//
// The pair is the identity, not the dirty mask alone: the same column
// assigned a bound value and assigned a server-side expression are two
// different statements, and the arguments of one do not fit the other.
//
// ret picks the cache as well as the suffix. The batch path passes
// false — it cannot read rows back, so it must not ask for them.
func stmtForKey(k runtime.MaskKey, ret bool) *runtime.Stmt {
	cache := updCache
	if !ret {
		cache = updOpCache
	}
	if st := cache.Get(k); st != nil {
		return st
	}
	set := make([]runtime.Frag, 0, nUpdatable+1)
	for i := 0; i < nUpdatable; i++ {
		// An expression wins: a column set both ways cannot happen,
		// because each setter clears the other's bit.
		switch {
		case k.Expr&(1<<uint(i)) != 0:
			set = append(set, exprFrags[i])
		case k.Dirty&(1<<uint(i)) != 0:
			set = append(set, setFrags[i])
		}
	}
	where := make([]runtime.Frag, 0, 3)
	where = append(where, pkFrags[:]...)
	// A deleted row is not updatable: every read here says it is gone.
	where = append(where, runtime.Frag{A: `"deleted_at" IS NULL`})
	// Only an expression needs reading back. A plain UPDATE already
	// knows every value it wrote, so it pays no RETURNING.
	suffix := ""
	if ret && k.Expr != 0 {
		suffix = updReturning
	}
	return cache.Put(k, runtime.SpliceSections(updatePrefix, []runtime.Section{
		{Lead: "", Sep: ", ", Frags: set},
		{Lead: " WHERE ", Sep: " AND ", Frags: where},
	}, suffix))
}

// Update writes the assigned columns of one row.
//
// Assigning nothing is not an error and issues no statement — an UPDATE
// with an empty SET list is not valid SQL, and a caller looping over
// possibly-changed fields should not have to special-case the empty case.
//
// An assignment the DATABASE computes is read back in the same
// statement, so m.Row() is the row that now exists rather than the
// one that used to. A second SELECT would race every other writer,
// which is the same reason Insert reads its row back.
func (m *Mut) Update(ctx context.Context, ex runtime.Executor) error {
	if m.dirty == 0 && m.expr == 0 {
		return nil
	}
	st := stmtForKey(m.key(), true)
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return st.Err
	}
	args := make([]any, 0, st.NArg)
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.UpdatedAt)
		case 1:
			args = append(args, m.row.ProjectID)
		case 2:
			args = append(args, m.row.DefinitionID)
		case 3:
			args = append(args, m.row.ParentInstanceID.Arg())
		case 4:
			args = append(args, m.row.ParentNodeID.Arg())
		case 5:
			args = append(args, m.row.Status)
		case 6:
			args = append(args, m.row.BusinessKey.Arg())
		case 7:
			args = append(args, m.row.Variables)
		case 8:
			args = append(args, m.row.Tokens)
		case 9:
			args = append(args, m.row.CompletedNodes)
		case 10:
			args = append(args, m.row.CompensatedNodes)
		case 11:
			args = append(args, m.row.MultiInstance)
		case 12:
			args = append(args, m.row.Joins)
		case 13:
			args = append(args, m.row.DeletedAt.Arg())
		}
	}
	args = append(args, m.row.ID)
	if m.expr != 0 {
		return m.updateReturning(ctx, ex, st, args)
	}
	n, err := ex.Exec(ctx, st.SQL, args)
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	m.dirty = 0
	m.expr = 0
	return nil
}

// updateReturning runs an UPDATE that let the database compute part of
// the row, and reads the whole row back into the staged copy.
//
// Every column, not just the computed ones: a trigger may have touched
// anything, and a staged row that is fresh in two fields and stale in
// the rest is harder to reason about than one that is simply current.
func (m *Mut) updateReturning(ctx context.Context, ex runtime.Executor, st *runtime.Stmt, args []any) error {
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return err
		}
		return runtime.ErrNoRow
	}
	// The staged row owns this arena, the way an inserted row does.
	var sl runtime.Slab
	if err := scan(rows.RawValues(), &m.row, &sl); err != nil {
		return err
	}
	if err := rows.Err(); err != nil {
		return err
	}
	m.dirty = 0
	m.expr = 0
	return nil
}

// softDeleteSQL marks one live row. It matches on `"deleted_at" IS NULL`, so
// deleting an already-deleted row reports runtime.ErrNoRow rather than
// silently re-stamping it with a later time.
var softDeleteSQL = runtime.SpliceSections(`UPDATE "process_instances" SET "deleted_at" = now()`, []runtime.Section{
	{Lead: " WHERE ", Sep: " AND ", Frags: append(pkFrags[:], runtime.Frag{A: `"deleted_at" IS NULL`})},
}, "").SQL

// Delete marks one row deleted. The row stays in the table and keeps its
// keys; every read generated in this package stops returning it.
//
// A row that was already deleted is runtime.ErrNoRow, not success — the
// same answer a hard delete gives for a row that is not there.
func Delete(ctx context.Context, ex runtime.Executor, iD [16]byte) error {
	n, err := ex.Exec(ctx, softDeleteSQL, []any{iD})
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	return nil
}

var hardDeleteSQL = runtime.SpliceSections(deletePrefix, []runtime.Section{
	{Lead: " WHERE ", Sep: " AND ", Frags: pkFrags[:]},
}, "").SQL

// HardDelete removes the row for real, deleted or not. It is the only
// function in this package that destroys data, which is why it is not
// spelled Delete.
func HardDelete(ctx context.Context, ex runtime.Executor, iD [16]byte) error {
	n, err := ex.Exec(ctx, hardDeleteSQL, []any{iD})
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	return nil
}

var restoreSQL = runtime.SpliceSections(`UPDATE "process_instances" SET "deleted_at" = NULL`, []runtime.Section{
	{Lead: " WHERE ", Sep: " AND ", Frags: append(pkFrags[:], runtime.Frag{A: `"deleted_at" IS NOT NULL`})},
}, "").SQL

// Restore clears the mark. A row that was not deleted is runtime.ErrNoRow:
// restoring something that was never gone is a caller believing something
// untrue about the row, and reporting success would leave them believing it.
func Restore(ctx context.Context, ex runtime.Executor, iD [16]byte) error {
	n, err := ex.Exec(ctx, restoreSQL, []any{iD})
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	return nil
}

// Set-based writes. Two caches of their own, keyed like the read
// caches by the predicate stream — UpdateAll's prefixed with the
// assignment masks, which are as much its identity as the predicates.
var (
	updAllCache   = runtime.NewTreeCache()
	delAllCache   = runtime.NewTreeCache()
	purgeAllCache = runtime.NewTreeCache()
)

// UpdateHead is UpdateAll's statement without its predicates, for the
// context package to narrow with a composed read: the UPDATE … SET, the
// identity a statement built from it is cached under, and the values m
// assigns. ok is false when m assigns nothing.
func (m Mut) UpdateHead() (head *runtime.Stmt, key [4]runtime.Tok, args []any, ok bool) {
	if m.dirty == 0 && m.expr == 0 {
		return nil, key, nil, false
	}
	key[0], key[1] = runtime.Tok(m.dirty), runtime.Tok(m.dirty>>32)
	key[2], key[3] = runtime.Tok(m.expr), runtime.Tok(m.expr>>32)
	return updHead(m.key()), key, m.updateArgs(nil), true
}

// updateArgs appends the values m assigns, in SET order.
func (m Mut) updateArgs(args []any) []any {
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.UpdatedAt)
		case 1:
			args = append(args, m.row.ProjectID)
		case 2:
			args = append(args, m.row.DefinitionID)
		case 3:
			args = append(args, m.row.ParentInstanceID.Arg())
		case 4:
			args = append(args, m.row.ParentNodeID.Arg())
		case 5:
			args = append(args, m.row.Status)
		case 6:
			args = append(args, m.row.BusinessKey.Arg())
		case 7:
			args = append(args, m.row.Variables)
		case 8:
			args = append(args, m.row.Tokens)
		case 9:
			args = append(args, m.row.CompletedNodes)
		case 10:
			args = append(args, m.row.CompensatedNodes)
		case 11:
			args = append(args, m.row.MultiInstance)
		case 12:
			args = append(args, m.row.Joins)
		case 13:
			args = append(args, m.row.DeletedAt.Arg())
		}
	}
	return args
}

// Shaped reports a Limit, Offset or row lock, which shape a read and
// which a set-based write composed around this query has no place for.
func (q Query) Shaped() bool {
	return q.limit != 1000 || q.offset != 0 || q.lock != 0
}

// writeAllErr is what UpdateAll and DeleteAll refuse.
func (q Query) writeAllErr() error {
	if err := q.Err(); err != nil {
		return err
	}
	if q.nt == 0 {
		return runtime.ErrUnfilteredWrite
	}
	if q.limit != 1000 || q.offset != 0 || q.lock != 0 {
		return runtime.ErrPagedWrite
	}
	return nil
}

var updHeadCache = runtime.NewMaskCache()

// updHead is the UPDATE … SET of one assignment mask, before the
// predicates or the read that narrow it.
func updHead(k runtime.MaskKey) *runtime.Stmt {
	if st := updHeadCache.Get(k); st != nil {
		return st
	}
	set := make([]runtime.Frag, 0, nUpdatable+1)
	for i := 0; i < nUpdatable; i++ {
		switch {
		case k.Expr&(1<<uint(i)) != 0:
			set = append(set, exprFrags[i])
		case k.Dirty&(1<<uint(i)) != 0:
			set = append(set, setFrags[i])
		}
	}
	return updHeadCache.Put(k, runtime.SpliceSections(updatePrefix, []runtime.Section{
		{Lead: "", Sep: ", ", Frags: set},
	}, ""))
}

// updAllStmtFor compiles one (assignments, predicates) pair, once.
func updAllStmtFor(k runtime.MaskKey, preds []runtime.Tok) *runtime.Stmt {
	return updAllStmtIn(updAllCache, "", k, preds)
}

func updAllStmtIn(c *runtime.TreeCache, suffix string, k runtime.MaskKey, preds []runtime.Tok) *runtime.Stmt {
	var key [25]runtime.Tok
	key[0], key[1] = runtime.Tok(k.Dirty), runtime.Tok(k.Dirty>>32)
	key[2], key[3] = runtime.Tok(k.Expr), runtime.Tok(k.Expr>>32)
	n := 4 + copy(key[4:], preds)
	if st := c.Get(key[:n]); st != nil {
		return st
	}
	head := updHead(k)
	if head.Err != nil {
		return head
	}
	return c.Put(key[:n], runtime.SpliceTreeWhereFrom(head.SQL, softDeleteWhere, preds, lowering, suffix, head.NArg))
}

// UpdateAll writes m's assigned columns to every row the query
// matches, in ONE statement, and reports how many it wrote:
//
//	var m Mut
//	m.Set…(v)            // bound values and server-side forms alike
//	n, err := New().Where(…).UpdateAll(ctx, ex, m)
//
// Only assigned columns are written, as for Update; nothing assigned
// issues no statement and reports 0. The query must have a predicate —
// runtime.ErrUnfilteredWrite otherwise — and must not carry Limit,
// Offset or a row lock, which a set-based UPDATE has no clause for:
// runtime.ErrPagedWrite. Order is ignored, as it is by Count.
//
// Deleted rows are not written: every read here says they are gone.
func (q Query) UpdateAll(ctx context.Context, ex runtime.Executor, m Mut) (int64, error) {
	if err := q.writeAllErr(); err != nil {
		return 0, err
	}
	if m.dirty == 0 && m.expr == 0 {
		return 0, nil
	}
	var buf [21]runtime.Tok
	st := updAllStmtFor(m.key(), q.preds(&buf))
	if st.Err != nil {
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	args := append(m.updateArgs(make([]any, 0, st.NArg)), q.bindPreds(b)...)
	return ex.Exec(ctx, st.SQL, args)
}

func delAllStmtFor(toks []runtime.Tok) *runtime.Stmt {
	if st := delAllCache.Get(toks); st != nil {
		return st
	}
	return delAllCache.Put(toks, runtime.SpliceTreeWhere(`UPDATE "process_instances" SET "deleted_at" = now()`, softDeleteWhere, toks, lowering, ""))
}

// DeleteAll marks every live row the query matches deleted, in ONE
// statement, and reports how many it marked — the set-based Delete,
// and like Delete it removes nothing: the rows keep their keys and
// every read here stops returning them. Rows already marked are not
// stamped again.
//
// The query must have a predicate — runtime.ErrUnfilteredWrite
// otherwise — and must not carry Limit, Offset or a row lock:
// runtime.ErrPagedWrite. Order is ignored, as it is by Count.
func (q Query) DeleteAll(ctx context.Context, ex runtime.Executor) (int64, error) {
	if err := q.writeAllErr(); err != nil {
		return 0, err
	}
	var buf [21]runtime.Tok
	st := delAllStmtFor(q.preds(&buf))
	if st.Err != nil {
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	return ex.Exec(ctx, st.SQL, q.bindPreds(b))
}

func purgeAllStmtFor(toks []runtime.Tok) *runtime.Stmt {
	if st := purgeAllCache.Get(toks); st != nil {
		return st
	}
	return purgeAllCache.Put(toks, runtime.SpliceTree(deletePrefix, toks, lowering, ""))
}

// HardDeleteAll removes every row the query matches for real, in ONE
// statement, marked deleted or not, and reports how many it removed —
// the set-based HardDelete. DeleteAll only marks them.
//
// The query must have a predicate — runtime.ErrUnfilteredWrite
// otherwise — and must not carry Limit, Offset or a row lock:
// runtime.ErrPagedWrite. Order is ignored, as it is by Count.
func (q Query) HardDeleteAll(ctx context.Context, ex runtime.Executor) (int64, error) {
	if err := q.writeAllErr(); err != nil {
		return 0, err
	}
	var buf [21]runtime.Tok
	st := purgeAllStmtFor(q.preds(&buf))
	if st.Err != nil {
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	return ex.Exec(ctx, st.SQL, q.bindPreds(b))
}

// The step this table's UpdateAll is, and the statements written after
// another table's step.
var updStepCache = runtime.NewTreeCache()

const stepReturning = ` RETURNING "id"`

// UpdateAllStep is UpdateAll as a step: it writes when the statement
// it is handed to runs, and that statement's write can count the rows it
// wrote. It refuses what UpdateAll refuses, and nothing assigned is
// refused with runtime.ErrNothingAssigned: a step that writes nothing
// would count nothing for a reason nobody asked for.
func (q Query) UpdateAllStep(m Mut) runtime.Step {
	return func(run func(string, []any) error) error {
		if err := q.writeAllErr(); err != nil {
			return err
		}
		if m.dirty == 0 && m.expr == 0 {
			return runtime.ErrNothingAssigned
		}
		var buf [21]runtime.Tok
		st := updAllStmtIn(updStepCache, stepReturning, m.key(), q.preds(&buf))
		if st.Err != nil {
			return st.Err
		}
		b := binders.Get()
		defer putBinder(b)
		args := make([]any, 0, st.NArg)
		for i := 0; i < nUpdatable; i++ {
			if m.dirty&(1<<uint(i)) == 0 {
				continue
			}
			switch i {
			case 0:
				args = append(args, m.row.UpdatedAt)
			case 1:
				args = append(args, m.row.ProjectID)
			case 2:
				args = append(args, m.row.DefinitionID)
			case 3:
				args = append(args, m.row.ParentInstanceID.Arg())
			case 4:
				args = append(args, m.row.ParentNodeID.Arg())
			case 5:
				args = append(args, m.row.Status)
			case 6:
				args = append(args, m.row.BusinessKey.Arg())
			case 7:
				args = append(args, m.row.Variables)
			case 8:
				args = append(args, m.row.Tokens)
			case 9:
				args = append(args, m.row.CompletedNodes)
			case 10:
				args = append(args, m.row.CompensatedNodes)
			case 11:
				args = append(args, m.row.MultiInstance)
			case 12:
				args = append(args, m.row.Joins)
			case 13:
				args = append(args, m.row.DeletedAt.Arg())
			}
		}
		return run(st.SQL, append(args, q.bindPreds(b)...))
	}
}

// ExistsStep is the existence probe as a step: at most one row, when
// the query matches any. A write after it can act on whether it did.
func (q Query) ExistsStep() runtime.Step {
	return func(run func(string, []any) error) error {
		if err := q.Err(); err != nil {
			return err
		}
		if q.lock != 0 {
			return errExistsLocked
		}
		var buf [21]runtime.Tok
		st := existsStmtFor(q.preds(&buf))
		if st.Err != nil {
			return st.Err
		}
		b := binders.Get()
		defer putBinder(b)
		return run(st.SQL, q.bindPreds(b))
	}
}
